<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f3f7f8"><title>Настройки системы — СБ</title><link rel="stylesheet" href="site-theme.css"><link rel="stylesheet" href="site-header.css">
<style>
*{box-sizing:border-box}body{margin:0;background:#f3f7f8;color:#18343a;font:14px/1.5 Inter,Arial,sans-serif}.page{max-width:1120px;margin:auto;padding:24px 16px 48px}.head{margin-bottom:18px}.head h1{font-size:25px;margin:0}.muted{color:#71858a;font-size:11px}.tabs{display:flex;gap:7px;flex-wrap:wrap;margin:15px 0}.tab{border:1px solid #dce7e9;background:#fff;border-radius:9px;padding:9px 13px;font-size:12px;font-weight:750;cursor:pointer;color:#18343a}.tab.active{background:#08777b;border-color:#08777b;color:#fff}.panel{background:#fff;border:1px solid #e1eaeb;border-radius:14px;padding:18px;margin-bottom:14px}.panel h2{font-size:16px;margin:0 0 5px}.panel p{font-size:11px;color:#71858a;margin:0 0 15px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.field{display:flex;flex-direction:column;gap:5px}.field.full{grid-column:1/-1}.field label{font-size:11px;font-weight:750}.field input,.field textarea{width:100%;padding:10px 11px;border:1px solid #dce7e9;border-radius:9px;font:13px Inter,Arial,sans-serif}.field textarea{min-height:84px;resize:vertical}.check{display:flex;align-items:center;gap:9px;padding:10px 0;font-size:12px;font-weight:650}.check input{width:17px;height:17px}.btn{border:1px solid #dce7e9;background:#fff;border-radius:9px;padding:9px 13px;font-size:12px;font-weight:750;cursor:pointer}.btn.primary{background:#08777b;border-color:#08777b;color:#fff}.actions{display:flex;justify-content:flex-end;gap:8px;margin-top:14px}.logo-preview{width:88px;height:88px;border-radius:14px;border:1px dashed #cbd9dc;display:grid;place-items:center;overflow:hidden;background:#f7faf9;color:#08777b;font-size:23px;font-weight:800}.logo-preview img{width:100%;height:100%;object-fit:contain}.template{padding:14px 0;border-top:1px solid #edf2f2}.template:first-of-type{border-top:0}.template h3{font-size:13px;margin:0 0 10px}.permission-table{width:100%;border-collapse:collapse;font-size:11px}.permission-table th,.permission-table td{padding:9px 8px;border-bottom:1px solid #edf2f2;text-align:center}.permission-table th:first-child,.permission-table td:first-child{text-align:left}.permission-table th{color:#71858a;font-size:10px}.permission-table input{width:17px;height:17px;accent-color:#08777b}.permission-table td:first-child{font-weight:650}.message{display:none;margin:10px 0;padding:10px 12px;border-radius:9px;font-size:12px}.message.error{display:block;background:#fff0ed;color:#a63f2d}.message.success{display:block;background:#eaf7f2;color:#176b55}.hint{font-size:10px;color:#71858a;margin-top:10px}.tab-panel[hidden]{display:none!important}@media(max-width:650px){.grid{grid-template-columns:1fr}.field.full{grid-column:auto}.permission-table th,.permission-table td{padding:7px 4px}.permission-table{font-size:10px}.permission-wrap{overflow-x:auto}}
</style></head><body>
