<main class="page"><div class="head"><h1>Настройки системы</h1><div class="muted">Название организации, логотип, уведомления, шаблоны и права ролей</div></div>
<div class="tabs"><button class="tab active" data-tab="general">Организация</button><button class="tab" data-tab="notifications">Уведомления</button><button class="tab" data-tab="templates">Шаблоны</button><button class="tab" data-tab="permissions">Права доступа</button></div>
<div id="message" class="message" role="status"></div>
<section class="tab-panel" id="tab-general"><form class="panel" id="generalForm"><h2>Оформление системы</h2><p>Эти данные будут отображаться в шапке сайта для всех сотрудников.</p><div class="grid"><div class="field"><label for="orgName">Название организации</label><input id="orgName" name="org_name" maxlength="120" required></div><div class="field"><label for="orgSubtitle">Подпись под названием</label><input id="orgSubtitle" name="org_subtitle" maxlength="160"></div><div class="field full"><label for="logo">Логотип (PNG, JPG или WEBP, до 2 МБ)</label><div class="grid"><div class="logo-preview" id="logoPreview">СБ</div><div class="field"><input id="logo" name="logo" type="file" accept="image/png,image/jpeg,image/webp"><label class="check"><input id="removeLogo" type="checkbox" name="remove_logo" value="1"> Удалить текущий логотип</label></div></div></div></div><div class="actions"><button class="btn primary" type="submit" id="saveGeneral">Сохранить оформление</button></div></form></section>
<section class="tab-panel" id="tab-notifications" hidden><form class="panel" id="notificationForm"><h2>Параметры уведомлений</h2><p>Настройки применяются ко всем новым системным уведомлениям.</p><label class="check"><input id="notificationsEnabled" type="checkbox" name="notifications_enabled"> Включить уведомления внутри сайта</label><label class="check"><input id="pushEnabled" type="checkbox" name="push_enabled"> Отправлять push-уведомления на подключённые устройства</label><div class="hint">Если отключить уведомления внутри сайта, новые сообщения не будут записываться. Push зависит от включённых уведомлений внутри сайта.</div><div class="actions"><button class="btn primary" type="submit">Сохранить параметры</button></div></form></section>
<section class="tab-panel" id="tab-templates" hidden><form class="panel" id="templatesForm"><h2>Стандартные шаблоны уведомлений</h2><p>Можно менять заголовок и текст сообщений, которые система отправляет сотрудникам.</p>
<div class="template"><h3>Новое происшествие</h3><div class="grid"><div class="field full"><label>Заголовок</label><input name="template_incident_created_title" maxlength="180" required></div><div class="field full"><label>Текст</label><textarea name="template_incident_created_body" maxlength="1000" required></textarea></div></div></div>
<div class="template"><h3>Возмещение ущерба</h3><div class="grid"><div class="field full"><label>Заголовок</label><input name="template_damage_payment_title" maxlength="180" required></div><div class="field full"><label>Текст</label><textarea name="template_damage_payment_body" maxlength="1000" required></textarea></div></div></div>
<div class="template"><h3>Ознакомление с документом</h3><div class="grid"><div class="field full"><label>Заголовок</label><input name="template_document_ack_title" maxlength="180" required></div><div class="field full"><label>Текст</label><textarea name="template_document_ack_body" maxlength="1000" required></textarea></div></div></div>
<div class="hint">Подстановки: {incident_id}, {object}, {title}, {date}, {amount}, {balance}. Для документа доступна {title}.</div><div class="actions"><button class="btn primary" type="submit">Сохранить шаблоны</button></div></form></section>
<section class="tab-panel" id="tab-permissions" hidden><div class="panel"><h2>Матрица прав доступа</h2><p>Настраиваются роли «Менеджер по безопасности» и «Специалист по безопасности». Администратор всегда сохраняет полный доступ. Ограничения по закреплённым торговым объектам продолжают действовать.</p><div class="permission-wrap"><table class="permission-table"><thead><tr><th>Возможность</th><th>Менеджер</th><th>Специалист</th></tr></thead><tbody id="permissionRows"><tr><td colspan="3">Загружаем права…</td></tr></tbody></table></div><div class="actions"><button class="btn" type="button" id="resetPermissions">Вернуть стандартные</button><button class="btn primary" type="button" id="savePermissions">Сохранить права доступа</button></div><div class="hint">Снятие флажка запрещает соответствующее действие и на сервере, а не только скрывает кнопку в интерфейсе.</div></div></section>
</main>
<script>
(function(){
'use strict';const $=id=>document.getElementById(id);let csrf='',catalog={},roles={},defaults={};
function node(tag,cls,txt){const n=document.createElement(tag);if(cls)n.className=cls;if(txt!==undefined)n.textContent=txt;return n;}
async function read(r){const raw=await r.text();let d;try{d=JSON.parse(raw);}catch(e){throw new Error('Некорректный ответ сервера.');}if(!r.ok||!d.ok)throw new Error(d.error||'Ошибка запроса.');if(d.csrf)csrf=d.csrf;return d;}
async function get(action){return read(await fetch('api.php?action='+action,{credentials:'same-origin',cache:'no-store',headers:{Accept:'application/json'}}));}
function show(text,kind){const n=$('message');n.textContent=text;n.className='message '+kind;}
function setTab(name){document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('active',b.dataset.tab===name));document.querySelectorAll('.tab-panel').forEach(p=>p.hidden=p.id!=='tab-'+name);}
document.querySelectorAll('.tab').forEach(b=>b.addEventListener('click',()=>setTab(b.dataset.tab)));
function renderPermissions(){const body=$('permissionRows');body.replaceChildren();Object.entries(catalog).forEach(([key,label])=>{const tr=node('tr'),td=node('td','',label);tr.append(td);['moderator','user'].forEach(role=>{const cell=node('td'),input=node('input');input.type='checkbox';input.dataset.role=role;input.dataset.permission=key;input.checked=!!(roles[role]&&roles[role][key]);cell.append(input);tr.append(cell);});body.append(tr);});}
function fillTemplates(rows){const byKey={};(rows||[]).forEach(x=>byKey[x.template_key]=x);['incident_created','damage_payment','document_ack'].forEach(key=>{const row=byKey[key]||{};$('templatesForm').elements['template_'+key+'_title'].value=row.title||'';$('templatesForm').elements['template_'+key+'_body'].value=row.body||'';});}
async function load(){
 const s=await get('status');if(!s.authenticated||!s.user||s.user.role!=='admin'){location.href='index.html';return;}csrf=s.csrf||'';
 const d=await get('settings_data');const v=d.settings||{};$('orgName').value=v.org_name||'';$('orgSubtitle').value=v.org_subtitle||'';$('notificationsEnabled').checked=v.notifications_enabled!=='0';$('pushEnabled').checked=v.push_enabled!=='0';
 $('logoPreview').replaceChildren();if(v.logo_file){const img=node('img');img.src='api.php?action=system_logo&v='+Date.now();img.alt='Логотип';$('logoPreview').append(img);}else $('logoPreview').textContent='СБ';
 fillTemplates(d.templates);
 const p=await get('permissions_data');catalog=p.catalog||{};roles=p.roles||{};defaults=p.defaults||{};renderPermissions();
}
async function saveSettings(form,button){button.disabled=true;const old=button.textContent;button.textContent='Сохраняем…';try{const fd=new FormData(form);fd.append('csrf',csrf);const d=await read(await fetch('api.php?action=settings_save',{method:'POST',credentials:'same-origin',body:fd}));show('Настройки сохранены.','success');await load();}catch(e){show(e.message,'error');}finally{button.disabled=false;button.textContent=old;}}
$('generalForm').addEventListener('submit',e=>{e.preventDefault();saveSettings(e.currentTarget,$('saveGeneral'));});
$('notificationForm').addEventListener('submit',e=>{e.preventDefault();saveSettings(e.currentTarget,e.currentTarget.querySelector('button[type=submit]'));});
$('templatesForm').addEventListener('submit',e=>{e.preventDefault();saveSettings(e.currentTarget,e.currentTarget.querySelector('button[type=submit]'));});
$('savePermissions').addEventListener('click',async()=>{const btn=$('savePermissions');btn.disabled=true;try{const values={moderator:{},user:{}};document.querySelectorAll('#permissionRows input').forEach(input=>values[input.dataset.role][input.dataset.permission]=input.checked);await read(await fetch('api.php?action=permissions_save',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify({csrf,roles:values})}));show('Права доступа сохранены. Изменения применятся при следующем обновлении страниц сотрудников.','success');await load();}catch(e){show(e.message,'error');}finally{btn.disabled=false;}});
$('resetPermissions').addEventListener('click',()=>{roles=JSON.parse(JSON.stringify(defaults));renderPermissions();show('Выбраны стандартные права. Нажмите «Сохранить права доступа», чтобы применить их.','success');});
$('logo').addEventListener('change',()=>{const file=$('logo').files[0];if(!file)return;const url=URL.createObjectURL(file);const img=node('img');img.src=url;img.alt='Предпросмотр логотипа';$('logoPreview').replaceChildren(img);});
load().catch(e=>show(e.message,'error'));
})();
</script><script>(function(){'use strict';function ping(){if(document.visibilityState!=='hidden')fetch('api.php?action=presence_ping',{credentials:'same-origin',cache:'no-store'}).catch(function(){});}ping();setInterval(ping,60000);document.addEventListener('visibilitychange',ping);})();</script><script src="site-header.js"></script>
</body></html>